sys_script_include.script:
var HSBCWORMTransferUtils = Class.create();
HSBCWORMTransferUtils.prototype = {
    initialize: function() {},
    WORMFileTransmit: function(content_type, request_id, application_id, signature, checksum, /*authorization,*/ fileName, attachmentSysId) {
        var upload_result = false;
        try {
            // initial RESTMessageV2
            var restMessage = new sn_ws.RESTMessageV2('x_hsb11_hsbc_mss_o.WORM API', 'WORM Upload');
            restMessage.setStringParameterNoEscape('worm_uri', gs.getProperty('x_hsb11_hsbc_mss_t.worm_API_endpoint'));
            restMessage.setRequestHeader('Content-Type', content_type);
            restMessage.setRequestHeader('x-application-id', application_id);
            restMessage.setRequestHeader('x-signature', signature);
            restMessage.setRequestHeader('X-Request-Id', request_id);
            restMessage.setRequestHeader('x-checksum', checksum);
            //restMessage.setRequestHeader('Authorization', authorization);
            restMessage.setRequestHeader('x-fileName', fileName);

            //  setRequestBodyFromAttachment 
            restMessage.setRequestBodyFromAttachment(attachmentSysId);

            restMessage.setHttpTimeout(10000); // 10 seconds

            // send request
            var response = restMessage.execute();
            var httpStatus = response.getStatusCode();
            var responseBody = response.getBody();

            // checking file transmission result
            if (httpStatus >= 200 && httpStatus < 300) {
                gs.info('HSBCWORMTransferUtils - Attached file: ' + attachmentSysId + ' transfered to WORM successfully.');
                upload_result = true;
            } else {
                // print result
                gs.info('HSBCWORMTransferUtils - HTTP Status Code: ' + httpStatus);
                gs.info('HSBCWORMTransferUtils - Response Body: ' + responseBody);
                gs.warn('HSBCWORMTransferUtils - Transfered Attached file: ' + attachmentSysId + ' failed with status code: ' + httpStatus);
            }
        } catch (error) {
            // catch exception
            gs.error('HSBCWORMTransferUtils - Error during transfer file to WORM: ' + error.message);
        }
        return upload_result;
    },

    getFileNameById: function(attachmentId) {
        if (!attachmentId) {
            return 'Invalid sys_id';
        }
        var attach_gr = new GlideRecord('sys_attachment');
        if (attach_gr.get(attachmentId)) {
            return attach_gr.getValue('file_name');
        } else {
            return 'Attachment not found';
        }
    },

    type: 'HSBCWORMTransferUtils'
};
